#include <iostream>

namespace Direction {
    enum Value { Left, Right };
}

class Player {
public:
    int left = 1;
    int right = 2;
    int f(Direction::Value dir) {
        if (dir == Direction::Left) return left;
        else if (dir == Direction::Right) return right;
        return 0;
    }
};

int main() {
    Player p;
    int result1 = p.f(Direction::Left); // Using scope resolution to specify namespace
    int result2 = p.f(Direction::Right); // Using scope resolution for enum values
    int result3 = p.f(p.left); // Direct call with member variable
    std::cout << "Results: " << result1 << ", " << result2 << ", " << result3 << std::endl;
    return 0;
}
